#include <iostream>
#include <string>
#include <utility>
using namespace std;

int main() {
    string s = "hello, cppmind";
    cout << "move 前: s = \"" << s << "\", size=" << s.size() << "\n";

    string t = std::move(s);   // std::move 本身只做 cast；搬数据的是移动构造函数

    cout << "move 后: t = \"" << t << "\"\n";
    cout << "move 后: s.size() = " << s.size()
         << "  （被移动对象处于「有效但未指定」状态）\n";

    s = "reused";
    cout << "重新赋值后: s = \"" << s << "\"，说明它仍然有效\n";
    cout << "结论: std::move 一行数据都不会搬，它只把左值转成右值引用\n";
}
